import type { ReactNode } from "react";

export type MetricTrend = {
  value: number;
  direction: "up" | "down" | "flat";
  positiveWhen?: "up" | "down";
  comparison?: string;
};
export type MetricCardProps = {
  label: string;
  value: string | number;
  locale?: string;
  prefix?: string;
  suffix?: string;
  period?: string;
  trend?: MetricTrend;
  loading?: boolean;
  note?: ReactNode;
};

/** A single semantic KPI, usable in dashboard or presentation contexts. */
export function P0MetricCard({
  label, value, locale = "en-BD", prefix = "", suffix = "",
  period, trend, loading = false, note,
}: MetricCardProps) {
  const formatted = typeof value === "number" && Number.isFinite(value)
    ? new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(value)
    : String(value);
  const isPositive = trend && trend.direction !== "flat" &&
    trend.direction === (trend.positiveWhen ?? "up");
  const delta = trend && (
    <span className={"pcl-metric__trend " +
      (trend.direction === "flat" ? "pcl-metric__trend--neutral" :
        isPositive ? "pcl-metric__trend--positive" : "pcl-metric__trend--negative")}>
      {trend.direction === "up" ? "↑" : trend.direction === "down" ? "↓" : "•"} {Math.abs(trend.value).toLocaleString(locale)}%
      {trend.comparison && <span className="pcl-metric__comparison"> {trend.comparison}</span>}
    </span>
  );
  return (
    <article className="pcl-metric" aria-label={label} aria-busy={loading}>
      <div className="pcl-metric__top"><span>{label}</span>{period && <small>{period}</small>}</div>
      <div className="pcl-metric__value" aria-live="off">{loading ? "…" : prefix + formatted + suffix}</div>
      <div className="pcl-metric__bottom">{loading ? <span role="status">Loading metric</span> : delta}{note && <span>{note}</span>}</div>
    </article>
  );
}

export function P0ProgressMeter({ label, value, max, locale = "en-BD" }: {
  label: string; value: number; max: number; locale?: string;
}) {
  const valid = Number.isFinite(value) && Number.isFinite(max) && max > 0;
  const bounded = valid ? Math.max(0, Math.min(max, value)) : 0;
  const percentage = valid ? Math.round(bounded / max * 100) : 0;
  return (
    <div className="pcl-meter">
      <div className="pcl-meter__labels"><strong>{label}</strong><span>{valid ? new Intl.NumberFormat(locale).format(value) + " / " + new Intl.NumberFormat(locale).format(max) : "No target"}</span></div>
      <div className="pcl-meter__track" role="progressbar" aria-label={label}
        aria-valuemin={0} aria-valuemax={valid ? max : 100} aria-valuenow={bounded}
        aria-valuetext={valid ? percentage + "%" : "No valid target"}>
        <span style={{ width: percentage + "%" }} />
      </div>
    </div>
  );
}

/* Scoped, source-owned P0 UI styles; safe to import into existing applications. */
.pcl-today,.pcl-metric{--pcl-ink:#1e2b32;--pcl-soft:#657782;--pcl-line:#e4e9e9;--pcl-bg:#fff;--pcl-accent:#295763;color:var(--pcl-ink);background:var(--pcl-bg);border:1px solid var(--pcl-line);border-radius:16px;box-shadow:0 7px 26px #1e303508}
.pcl-today{padding:23px}
.pcl-today__head,.pcl-today__footer,.pcl-task,.pcl-metric__top,.pcl-metric__bottom,.pcl-meter__labels{display:flex;justify-content:space-between;align-items:center;gap:12px}
.pcl-today__eyebrow{font-size:10px;font-weight:700;letter-spacing:.14em;color:#7b8d96}
.pcl-today h2{margin:5px 0 0;font-size:24px;line-height:1.16;letter-spacing:-.04em}
.pcl-today__count{font-size:11px;padding:7px 11px;border-radius:99px;background:#eff3f4;color:#486571;white-space:nowrap}
.pcl-today__list{list-style:none;margin:19px 0 0;padding:0}
.pcl-task{align-items:flex-start;border-top:1px solid var(--pcl-line);padding:15px 0}
.pcl-task__main{display:flex;align-items:flex-start;gap:12px;min-width:0;flex:1;cursor:pointer}
.pcl-task__main input{width:18px;height:18px;margin:2px 0 0;accent-color:var(--pcl-accent);flex-shrink:0}
.pcl-task__body{min-width:0;display:grid;gap:7px}
.pcl-task__title{font-size:13px;font-weight:590;line-height:1.45;overflow-wrap:anywhere}
.pcl-task--done .pcl-task__title{text-decoration:line-through;color:#89979e}
.pcl-task__meta{display:flex;flex-wrap:wrap;gap:8px;color:var(--pcl-soft);font-size:10px}
.pcl-priority{text-transform:capitalize;color:#6f7480}.pcl-priority--high{color:#b05745;font-weight:700}.pcl-priority--medium{color:#946f34}
.pcl-task__actions{display:flex;flex-wrap:wrap;gap:6px}
.pcl-task__actions button,.pcl-task__promote summary,.pcl-today__add{padding:6px 9px;border:1px solid #dce5e8;border-radius:7px;background:#fff;font-size:11px;color:#365d6e;cursor:pointer}
.pcl-task__promote{position:relative}
.pcl-task__promote summary{list-style:none}.pcl-task__promote summary::-webkit-details-marker{display:none}
.pcl-task__promotion-choices{position:absolute;right:0;top:calc(100% + 4px);z-index:10;background:#fff;border:1px solid var(--pcl-line);padding:7px;border-radius:9px;box-shadow:0 10px 20px #152d3a20;display:grid;gap:4px;min-width:110px}
.pcl-task__promotion-choices button{text-align:left}
.pcl-today__footer{border-top:1px solid var(--pcl-line);padding-top:15px;margin-top:4px}
.pcl-today__error{padding:12px;margin-top:14px;border-radius:8px;background:#fff5f2;color:#a63f2e;font-size:12px}
.pcl-today__notice{color:var(--pcl-soft);padding:22px 0;font-size:13px}
.pcl-metric{padding:21px 23px;min-width:0}
.pcl-metric__top{font-size:12px;font-weight:630;color:#586b74}
.pcl-metric__top small{color:#89969e;font-size:10px;font-weight:400}
.pcl-metric__value{font-size:clamp(26px,4vw,47px);font-weight:640;line-height:1.16;letter-spacing:-.06em;overflow-wrap:anywhere;margin:13px 0}
.pcl-metric__bottom{justify-content:flex-start;font-size:11px;color:var(--pcl-soft)}
.pcl-metric__trend{font-weight:700}.pcl-metric__trend--positive{color:#28744b}.pcl-metric__trend--negative{color:#bc554b}.pcl-metric__trend--neutral{color:#59636d}
.pcl-metric__comparison{font-weight:400;color:#687781}
.pcl-meter{display:grid;gap:10px;margin:14px 0}.pcl-meter__labels{font-size:12px}.pcl-meter__labels span{font-size:11px;color:#687781}
.pcl-meter__track{height:8px;background:#e7ecee;border-radius:99px;overflow:hidden}.pcl-meter__track span{display:block;height:100%;background:#315865;border-radius:99px;transition:width .24s ease}
.pcl-today button:focus-visible,.pcl-today summary:focus-visible,.pcl-today input:focus-visible{outline:3px solid #9cc6d5;outline-offset:3px}
@media(max-width:550px){.pcl-today{padding:16px}.pcl-task{display:grid;gap:12px}.pcl-task__actions{padding-left:30px}.pcl-task__promotion-choices{right:auto;left:0}}
@media(prefers-reduced-motion:reduce){.pcl-meter__track span{transition:none}}
